        0.25,
        0.25,
        0.25
      ]
    },
    {
      "color": "#ffffff",
      "count": 1,
      "offset": [
        0,
        1.6,
        0
      ],
      "spread": [
        0.1,
        0.1,
        0.1
      ]
    }
  ]
}
</code></pre> <pre><code>{
