  "directional_launch_particles": true,
  "charge_curve": "ease_in",
  "charge_particles": {
    "radius": 3,
    "count": 6,
    "rise_speed": 0.14,
    "lifetime": 26
  },
  "launch_particles": {
    "count": 60,
    "radius": 3.5,
    "strength": 0.5
  },
  "properties": {
    "title": "Takeoff"
  }
}
</code></pre> <pre><code>{
